export default {"file":"library-dashboard.html","title":"Library Dashboard - Schoolix","htmlClass":"","bodyClass":"library-dashboard-app","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<div class=\"library-app-layout\">\r\n    <div class=\"library-sidebar-overlay\" id=\"librarySidebarOverlay\" aria-hidden=\"true\"></div>\r\n    <aside class=\"library-sidebar\" id=\"librarySidebar\">\r\n        <div class=\"library-brand\">\r\n            <div class=\"library-brand-mark\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15Z\"></path><path d=\"M8 7h8\"></path></svg></div>\r\n            <div>\r\n                <strong>Schoolix</strong>\r\n                <span>Library Portal</span>\r\n            </div>\r\n        </div>\r\n        <nav class=\"library-nav\" aria-label=\"Library navigation\">\r\n            <div class=\"library-nav-label\">Library</div>\r\n            <a class=\"library-nav-link active\" href=\"#/library-dashboard.html\" aria-current=\"page\">\r\n                <span class=\"library-nav-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1.5\"></rect></svg></span>\r\n                Dashboard\r\n            </a>\r\n            <a class=\"library-nav-link\" href=\"librarian-#/notices.html\">\r\n                <span class=\"library-nav-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 11v2a2 2 0 0 0 2 2h2l4 4v-4h4l6 3V6l-6 3H5a2 2 0 0 0-2 2Z\"></path><path d=\"M21 9v6\"></path></svg></span>\r\n                Notices\r\n            </a>\r\n        </nav>\r\n        <div class=\"library-sidebar-footer\">Library records and notices in one workspace.</div>\r\n    </aside>\r\n    <main class=\"library-main\">\r\n<div class=\"container\">\r\n    <div class=\"library-hero card\">\r\n        <div class=\"top\">\r\n            <div class=\"hero-copy\">\r\n                <span class=\"eyebrow\">Library Workspace</span>\r\n                <h1>Library Dashboard</h1>\r\n                <p class=\"muted\" id=\"welcomeText\">Checking access...</p>\r\n            </div>\r\n            <div class=\"hero-actions\">\r\n                <button class=\"library-menu-button\" id=\"libraryMenuButton\" type=\"button\" aria-label=\"Open library navigation\" aria-expanded=\"false\">\r\n                    <svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16\"></path><path d=\"M4 12h16\"></path><path d=\"M4 18h16\"></path></svg>\r\n                </button>\r\n                <button class=\"btn btn-primary\" onclick=\"window.location.href='librarian-#/notices.html'\">\r\n                    <span class=\"btn-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 11v2a2 2 0 0 0 2 2h2l4 4v-4h4l6 3V6l-6 3H5a2 2 0 0 0-2 2Z\"></path><path d=\"M21 9v6\"></path></svg></span>\r\n                    Notices\r\n                </button>\r\n                <button class=\"logout-btn\" onclick=\"logout()\">\r\n                    <span class=\"btn-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"></path><path d=\"m16 17 5-5-5-5\"></path><path d=\"M21 12H9\"></path></svg></span>\r\n                    Logout\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card overview-card\">\r\n        <div class=\"section-head\">\r\n            <div>\r\n                <span class=\"eyebrow\">Live Register</span>\r\n                <h2>Quick Overview</h2>\r\n            </div>\r\n        </div>\r\n        <div class=\"stats\">\r\n            <div class=\"stat stat-students\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M23 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg></span>\r\n                <strong id=\"totalStudentsStat\">0</strong>\r\n                <span>Total Students</span>\r\n            </div>\r\n            <div class=\"stat stat-issued\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15Z\"></path><path d=\"M8 7h8\"></path><path d=\"M8 11h6\"></path></svg></span>\r\n                <strong id=\"issuedBooksStat\">0</strong>\r\n                <span>Issued Books</span>\r\n            </div>\r\n            <div class=\"stat stat-returned\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 6 9 17l-5-5\"></path></svg></span>\r\n                <strong id=\"returnedBooksStat\">0</strong>\r\n                <span>Returned Books</span>\r\n            </div>\r\n            <div class=\"stat stat-days\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"></rect><path d=\"M16 2v4\"></path><path d=\"M8 2v4\"></path><path d=\"M3 10h18\"></path></svg></span>\r\n                <strong id=\"maxDaysStat\">14</strong>\r\n                <span>Max Days Allowed</span>\r\n            </div>\r\n            <div class=\"stat stat-due\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 7v5l3 2\"></path></svg></span>\r\n                <strong id=\"dueTodayStat\">0</strong>\r\n                <span>Due Today</span>\r\n            </div>\r\n            <div class=\"stat stat-overdue\">\r\n                <span class=\"stat-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z\"></path><path d=\"M12 9v4\"></path><path d=\"M12 17h.01\"></path></svg></span>\r\n                <strong id=\"overdueBooksStat\">0</strong>\r\n                <span>Overdue Books</span>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card\">\r\n        <div class=\"section-head\">\r\n            <div>\r\n                <span class=\"eyebrow\">Shortcuts</span>\r\n                <h2>Quick Actions</h2>\r\n            </div>\r\n        </div>\r\n        <div class=\"quick-grid\">\r\n            <button class=\"quick-action\" onclick=\"focusIssueForm()\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14\"></path><path d=\"M5 12h14\"></path></svg></span><strong>Issue a Book</strong><span>Select student and enter book number</span></button>\r\n            <button class=\"quick-action\" onclick=\"showDueToday()\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 7v5l3 2\"></path></svg></span><strong>Due Today</strong><span>Books due today or earlier</span></button>\r\n            <button class=\"quick-action\" onclick=\"showOverdue()\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z\"></path><path d=\"M12 9v4\"></path><path d=\"M12 17h.01\"></path></svg></span><strong>Overdue Books</strong><span>Delayed returns only</span></button>\r\n            <button class=\"quick-action\" onclick=\"clearLibraryFilters()\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 6h18\"></path><path d=\"M7 12h10\"></path><path d=\"M10 18h4\"></path></svg></span><strong>Clear Filters</strong><span>Show complete issue register</span></button>\r\n            <button class=\"quick-action\" onclick=\"window.location.href='#/library-qr-checkin.html'\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 7V5a2 2 0 0 1 2-2h2\"></path><path d=\"M17 3h2a2 2 0 0 1 2 2v2\"></path><path d=\"M21 17v2a2 2 0 0 1-2 2h-2\"></path><path d=\"M7 21H5a2 2 0 0 1-2-2v-2\"></path><path d=\"M7 12h10\"></path></svg></span><strong>QR Check-In</strong><span>Open attendance scanner</span></button>\r\n            <button class=\"quick-action\" onclick=\"window.location.href='#/librarian-attendance.html'\"><span class=\"quick-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 11l3 3L22 4\"></path><path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"></path></svg></span><strong>My Attendance</strong><span>View daily records</span></button>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"grid-two\" id=\"issueRegister\">\r\n        <div class=\"card\">\r\n            <div class=\"section-head\">\r\n                <div>\r\n                    <span class=\"eyebrow\">Borrowers</span>\r\n                    <h2>All Students</h2>\r\n                </div>\r\n            </div>\r\n            <input id=\"studentSearch\" class=\"search-input\" placeholder=\"Search by Student ID or Name\">\r\n            <div class=\"list-toolbar\">\r\n                <label>Show\r\n                    <select id=\"studentPageSize\" class=\"select-input\" style=\"width:auto;margin-top:0;\">\r\n                        <option value=\"25\">25</option>\r\n                        <option value=\"50\">50</option>\r\n                        <option value=\"all\">All</option>\r\n                    </select>\r\n                    students\r\n                </label>\r\n                <div class=\"pager\" id=\"studentPager\"></div>\r\n            </div>\r\n            <div class=\"student-list\" id=\"studentList\"><div class=\"empty sx-inline-loading\">Loading students...</div></div>\r\n        </div>\r\n\r\n        <div class=\"card\">\r\n            <div class=\"section-head\">\r\n                <div>\r\n                    <span class=\"eyebrow\">Circulation</span>\r\n                    <h2>Issue Book</h2>\r\n                </div>\r\n            </div>\r\n            <input id=\"issueStudentId\" class=\"text-input\" placeholder=\"Student ID (e.g. SCH001)\">\r\n            <input id=\"issueBookNumber\" class=\"text-input\" placeholder=\"Book Number\">\r\n            <input id=\"issueBookTitle\" class=\"text-input\" placeholder=\"Book Title (optional)\">\r\n            <div class=\"selected-student\" id=\"selectedStudentCard\"><strong>No student selected</strong>Select a student from the list or type Student ID manually.</div>\r\n            <button class=\"btn btn-primary issue-submit\" style=\"margin-top: 10px;\" onclick=\"issueBook()\">\r\n                <span class=\"btn-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15Z\"></path><path d=\"M12 6v8\"></path><path d=\"M8 10h8\"></path></svg></span>\r\n                Issue Book\r\n            </button>\r\n            <p class=\"muted\" style=\"margin-top: 10px;\">Tip: Student row pe click karke ID auto-fill ho jayega.</p>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card\">\r\n        <div class=\"section-head\">\r\n            <div>\r\n                <span class=\"eyebrow\">Policy</span>\r\n                <h2>Library Rules</h2>\r\n            </div>\r\n        </div>\r\n        <div class=\"settings-row\">\r\n            <div>\r\n                <label for=\"maxDaysInput\">Max number of days books permitted</label>\r\n                <input id=\"maxDaysInput\" class=\"text-input\" type=\"number\" min=\"1\" max=\"365\" placeholder=\"e.g. 14\">\r\n                <p class=\"muted\" style=\"margin-top: 8px;\">Return date student panel me automatically isi value se calculate hoga.</p>\r\n            </div>\r\n            <button class=\"btn btn-primary\" onclick=\"saveLibrarySettings()\">\r\n                <span class=\"btn-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z\"></path><path d=\"M17 21v-8H7v8\"></path><path d=\"M7 3v5h8\"></path></svg></span>\r\n                Save Rules\r\n            </button>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card\">\r\n        <div class=\"section-head\">\r\n            <div>\r\n                <span class=\"eyebrow\">Issue Register</span>\r\n                <h2>Issued / Returned Books</h2>\r\n            </div>\r\n        </div>\r\n        <div class=\"filters\">\r\n            <input id=\"issueSearch\" class=\"search-input\" placeholder=\"Search by Book Number, Title, Student ID or Name\">\r\n            <select id=\"statusFilter\" class=\"select-input\">\r\n                <option value=\"all\">All</option>\r\n                <option value=\"issued\">Only Issued</option>\r\n                <option value=\"returned\">Only Returned</option>\r\n            </select>\r\n            <input id=\"issueAgeFilter\" class=\"text-input\" type=\"number\" min=\"0\" placeholder=\"Issued at least N days ago\">\r\n            <select id=\"dueFilter\" class=\"select-input\">\r\n                <option value=\"all\">All Due Dates</option>\r\n                <option value=\"due-now\">Due / Overdue Today</option>\r\n                <option value=\"overdue\">Overdue Only</option>\r\n            </select>\r\n        </div>\r\n        <div class=\"issue-list\" id=\"issueList\"><div class=\"empty sx-inline-loading\">Loading issue records...</div></div>\r\n    </div>\r\n</div>\r\n    </main>\r\n</div>\r\n\r\n<script src=\"school-branding.js\"></script>\r\n<script type=\"module\">\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged, signOut } from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    getDoc,\r\n    collection,\r\n    getDocs,\r\n    addDoc,\r\n    updateDoc,\r\n    setDoc,\r\n    serverTimestamp\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst welcomeText = document.getElementById(\"welcomeText\");\r\nconst studentListEl = document.getElementById(\"studentList\");\r\nconst issueListEl = document.getElementById(\"issueList\");\r\nconst totalStudentsStatEl = document.getElementById(\"totalStudentsStat\");\r\nconst issuedBooksStatEl = document.getElementById(\"issuedBooksStat\");\r\nconst returnedBooksStatEl = document.getElementById(\"returnedBooksStat\");\r\nconst maxDaysStatEl = document.getElementById(\"maxDaysStat\");\r\nconst dueTodayStatEl = document.getElementById(\"dueTodayStat\");\r\nconst overdueBooksStatEl = document.getElementById(\"overdueBooksStat\");\r\nconst studentSearchEl = document.getElementById(\"studentSearch\");\r\nconst studentPageSizeEl = document.getElementById(\"studentPageSize\");\r\nconst studentPagerEl = document.getElementById(\"studentPager\");\r\nconst issueSearchEl = document.getElementById(\"issueSearch\");\r\nconst statusFilterEl = document.getElementById(\"statusFilter\");\r\nconst issueAgeFilterEl = document.getElementById(\"issueAgeFilter\");\r\nconst dueFilterEl = document.getElementById(\"dueFilter\");\r\nconst issueStudentIdEl = document.getElementById(\"issueStudentId\");\r\nconst issueBookNumberEl = document.getElementById(\"issueBookNumber\");\r\nconst issueBookTitleEl = document.getElementById(\"issueBookTitle\");\r\nconst issueSubmitButtonEl = document.querySelector(\".issue-submit\");\r\nconst maxDaysInputEl = document.getElementById(\"maxDaysInput\");\r\nconst selectedStudentCardEl = document.getElementById(\"selectedStudentCard\");\r\nconst librarySidebarEl = document.getElementById(\"librarySidebar\");\r\nconst librarySidebarOverlayEl = document.getElementById(\"librarySidebarOverlay\");\r\nconst libraryMenuButtonEl = document.getElementById(\"libraryMenuButton\");\r\n\r\nlet adminId = null;\r\nlet currentLibrarian = null;\r\nlet librarySettings = { maxDays: 14 };\r\nlet students = [];\r\nlet issues = [];\r\nlet filteredStudents = [];\r\nlet filteredIssues = [];\r\nlet studentPage = 1;\r\n\r\nfunction closeLibrarySidebar() {\r\n    librarySidebarEl?.classList.remove(\"open\");\r\n    librarySidebarOverlayEl?.classList.remove(\"open\");\r\n    librarySidebarOverlayEl?.setAttribute(\"aria-hidden\", \"true\");\r\n    libraryMenuButtonEl?.setAttribute(\"aria-expanded\", \"false\");\r\n}\r\n\r\nfunction openLibrarySidebar() {\r\n    librarySidebarEl?.classList.add(\"open\");\r\n    librarySidebarOverlayEl?.classList.add(\"open\");\r\n    librarySidebarOverlayEl?.setAttribute(\"aria-hidden\", \"false\");\r\n    libraryMenuButtonEl?.setAttribute(\"aria-expanded\", \"true\");\r\n}\r\n\r\nlibraryMenuButtonEl?.addEventListener(\"click\", () => {\r\n    librarySidebarEl?.classList.contains(\"open\") ? closeLibrarySidebar() : openLibrarySidebar();\r\n});\r\nlibrarySidebarOverlayEl?.addEventListener(\"click\", closeLibrarySidebar);\r\nlibrarySidebarEl?.querySelectorAll(\"a\").forEach((link) => link.addEventListener(\"click\", closeLibrarySidebar));\r\ndocument.addEventListener(\"keydown\", (event) => {\r\n    if (event.key === \"Escape\") closeLibrarySidebar();\r\n});\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n    if (!userDoc.exists() || userDoc.data().role !== \"librarian\") {\r\n        alert(\"Access denied. Librarian account required.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const data = userDoc.data();\r\n    adminId = data.adminId || data.schoolId || \"\";\r\n    currentLibrarian = {\r\n        uid: user.uid,\r\n        name: data.name || \"Librarian\",\r\n        email: data.email || user.email || \"\"\r\n    };\r\n    if (!adminId) {\r\n        alert(\"Admin mapping missing for librarian account.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n    welcomeText.textContent = `Welcome ${data.name || \"Librarian\"} (${data.email || user.email})`;\r\n    await loadLibrarySettings();\r\n    await loadStudents();\r\n    await loadIssues();\r\n});\r\n\r\nwindow.logout = async () => {\r\n    try {\r\n        await signOut(auth);\r\n        window.location.href = \"#/index.html\";\r\n    } catch (error) {\r\n        alert(\"Logout failed.\");\r\n    }\r\n};\r\n\r\nfunction esc(value) {\r\n    return String(value ?? \"\")\r\n        .replace(/&/g, \"&amp;\")\r\n        .replace(/</g, \"&lt;\")\r\n        .replace(/>/g, \"&gt;\")\r\n        .replace(/\"/g, \"&quot;\")\r\n        .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction normalizeMaxDays(value) {\r\n    const days = Number(value);\r\n    if (!Number.isFinite(days) || days < 1) return 14;\r\n    return Math.min(365, Math.floor(days));\r\n}\r\n\r\nfunction toDate(value) {\r\n    if (!value) return null;\r\n    if (value.toDate) return value.toDate();\r\n    if (typeof value.seconds === \"number\") return new Date(value.seconds * 1000);\r\n    const parsed = new Date(value);\r\n    return Number.isNaN(parsed.getTime()) ? null : parsed;\r\n}\r\n\r\nfunction addDays(date, days) {\r\n    const result = new Date(date);\r\n    result.setDate(result.getDate() + days);\r\n    return result;\r\n}\r\n\r\nfunction getIssuedDate(entry) {\r\n    return toDate(entry.issuedAt) || toDate(entry.issuedAtMs);\r\n}\r\n\r\nfunction getMaxDaysForEntry(entry) {\r\n    return normalizeMaxDays(entry.maxDaysAllowed || librarySettings.maxDays);\r\n}\r\n\r\nfunction getDueDate(entry) {\r\n    const storedDueDate = toDate(entry.dueDate) || toDate(entry.dueDateMs);\r\n    if (storedDueDate) return storedDueDate;\r\n    const issued = getIssuedDate(entry);\r\n    return issued ? addDays(issued, getMaxDaysForEntry(entry)) : null;\r\n}\r\n\r\nfunction getIssueAgeDays(entry) {\r\n    const issued = getIssuedDate(entry);\r\n    if (!issued) return null;\r\n    return Math.max(0, Math.floor((Date.now() - issued.getTime()) / 86400000));\r\n}\r\n\r\nfunction isOverdue(entry) {\r\n    if (entry.status === \"returned\") return false;\r\n    const dueDate = getDueDate(entry);\r\n    if (!dueDate) return false;\r\n    const startOfToday = new Date();\r\n    startOfToday.setHours(0, 0, 0, 0);\r\n    return dueDate.getTime() < startOfToday.getTime();\r\n}\r\n\r\nfunction isDueToday(entry) {\r\n    if (entry.status === \"returned\") return false;\r\n    const dueDate = getDueDate(entry);\r\n    if (!dueDate) return false;\r\n    const endOfToday = new Date();\r\n    endOfToday.setHours(23, 59, 59, 999);\r\n    return dueDate.getTime() <= endOfToday.getTime();\r\n}\r\n\r\nfunction formatDateTime(value) {\r\n    const date = toDate(value);\r\n    return date ? date.toLocaleString() : \"N/A\";\r\n}\r\n\r\nfunction formatDateOnly(value) {\r\n    const date = toDate(value);\r\n    return date ? date.toLocaleDateString() : \"N/A\";\r\n}\r\n\r\nasync function loadLibrarySettings() {\r\n    try {\r\n        const settingsSnap = await getDoc(doc(db, \"schools\", adminId, \"settings\", \"library\"));\r\n        librarySettings = {\r\n            maxDays: normalizeMaxDays(settingsSnap.exists() ? settingsSnap.data().maxDays : 14)\r\n        };\r\n    } catch (error) {\r\n        console.warn(\"Library settings load failed:\", error);\r\n        librarySettings = { maxDays: 14 };\r\n    }\r\n    maxDaysInputEl.value = String(librarySettings.maxDays);\r\n    maxDaysStatEl.textContent = librarySettings.maxDays;\r\n}\r\n\r\nwindow.saveLibrarySettings = async () => {\r\n    const maxDays = normalizeMaxDays(maxDaysInputEl.value);\r\n    try {\r\n        await setDoc(doc(db, \"schools\", adminId, \"settings\", \"library\"), {\r\n            maxDays,\r\n            updatedAt: serverTimestamp(),\r\n            updatedBy: auth.currentUser.uid\r\n        }, { merge: true });\r\n        librarySettings.maxDays = maxDays;\r\n        maxDaysInputEl.value = String(maxDays);\r\n        maxDaysStatEl.textContent = maxDays;\r\n        renderIssues();\r\n        alert(\"Library rules saved.\");\r\n    } catch (error) {\r\n        console.error(\"Library settings save failed:\", error);\r\n        alert(\"Failed to save library rules.\");\r\n    }\r\n};\r\n\r\nasync function loadStudents() {\r\n    studentListEl.innerHTML = '<div class=\"empty sx-inline-loading\">Loading students...</div>';\r\n    try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", adminId, \"students\"));\r\n        students = snapshot.docs.map((docSnap) => ({\r\n            id: docSnap.id,\r\n            ...docSnap.data()\r\n        }));\r\n        filteredStudents = [...students];\r\n        totalStudentsStatEl.textContent = students.length;\r\n        renderStudents();\r\n    } catch (error) {\r\n        console.error(\"Failed to load students:\", error);\r\n        studentListEl.innerHTML = '<div class=\"empty\">Failed to load students.</div>';\r\n    }\r\n}\r\n\r\nfunction renderStudents() {\r\n    studentListEl.innerHTML = \"\";\r\n    if (filteredStudents.length === 0) {\r\n        studentListEl.innerHTML = '<div class=\"empty\">No students found.</div>';\r\n        renderStudentPager(0, 0, 1);\r\n        return;\r\n    }\r\n\r\n    const pageSizeValue = studentPageSizeEl?.value || \"25\";\r\n    const pageSize = pageSizeValue === \"all\" ? filteredStudents.length : Number(pageSizeValue || 25);\r\n    const totalPages = Math.max(1, Math.ceil(filteredStudents.length / Math.max(1, pageSize)));\r\n    studentPage = Math.min(Math.max(1, studentPage), totalPages);\r\n    const start = pageSizeValue === \"all\" ? 0 : (studentPage - 1) * pageSize;\r\n    const visibleStudents = pageSizeValue === \"all\" ? filteredStudents : filteredStudents.slice(start, start + pageSize);\r\n\r\n    visibleStudents.forEach((student) => {\r\n        const tc = !!student.tcIssued;\r\n        const row = document.createElement(\"div\");\r\n        row.className = \"row\" + (tc ? \" row-tc\" : \"\");\r\n        row.innerHTML = `\r\n            <div class=\"row-main\">\r\n                <span class=\"row-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 21a8 8 0 0 1 16 0\"></path></svg></span>\r\n                <div>\r\n                    <strong>${student.name || \"N/A\"}</strong>\r\n                    ${tc ? ' <span class=\"pill pill-tc\">TC Issued</span>' : \"\"}<br>\r\n                    <small>ID: ${student.studentId || \"N/A\"} | Class: ${student.class || \"-\"}-${student.section || \"-\"}</small>\r\n                    ${tc ? \"<br><small style=\\\"color:#b91c1c;\\\">Books cannot be issued - student has left (TC).</small>\" : \"\"}\r\n                </div>\r\n            </div>\r\n            <button class=\"btn btn-success\" ${tc ? \"disabled\" : \"\"}>${tc ? \"Blocked\" : \"Select\"}</button>\r\n        `;\r\n        const btn = row.querySelector(\"button\");\r\n        btn.addEventListener(\"click\", () => {\r\n            if (tc) {\r\n                alert(\"This student has a Transfer Certificate issued. Library issue is not allowed.\");\r\n                return;\r\n            }\r\n            issueStudentIdEl.value = student.studentId || \"\";\r\n            updateSelectedStudentCard(student);\r\n            issueStudentIdEl.focus();\r\n        });\r\n        studentListEl.appendChild(row);\r\n    });\r\n    renderStudentPager(filteredStudents.length, visibleStudents.length, totalPages);\r\n}\r\n\r\nfunction renderStudentPager(total, visible, totalPages) {\r\n    if (!studentPagerEl) return;\r\n    if (!total) {\r\n        studentPagerEl.innerHTML = \"\";\r\n        return;\r\n    }\r\n    const pageSizeValue = studentPageSizeEl?.value || \"25\";\r\n    const start = pageSizeValue === \"all\" ? 1 : ((studentPage - 1) * Number(pageSizeValue) + 1);\r\n    const end = pageSizeValue === \"all\" ? total : Math.min(total, start + visible - 1);\r\n    studentPagerEl.innerHTML = `\r\n        <span>${start}-${end} of ${total}</span>\r\n        <button type=\"button\" id=\"studentPrevPage\" ${studentPage <= 1 || pageSizeValue === \"all\" ? \"disabled\" : \"\"}>Prev</button>\r\n        <span>Page ${pageSizeValue === \"all\" ? 1 : studentPage}/${pageSizeValue === \"all\" ? 1 : totalPages}</span>\r\n        <button type=\"button\" id=\"studentNextPage\" ${studentPage >= totalPages || pageSizeValue === \"all\" ? \"disabled\" : \"\"}>Next</button>\r\n    `;\r\n    document.getElementById(\"studentPrevPage\")?.addEventListener(\"click\", () => {\r\n        studentPage = Math.max(1, studentPage - 1);\r\n        renderStudents();\r\n    });\r\n    document.getElementById(\"studentNextPage\")?.addEventListener(\"click\", () => {\r\n        studentPage = Math.min(totalPages, studentPage + 1);\r\n        renderStudents();\r\n    });\r\n}\r\n\r\nasync function loadIssues() {\r\n    issueListEl.innerHTML = '<div class=\"empty sx-inline-loading\">Loading issue records...</div>';\r\n    try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", adminId, \"library_issues\"));\r\n        issues = snapshot.docs.map((docSnap) => ({\r\n            id: docSnap.id,\r\n            ...docSnap.data()\r\n        }));\r\n        filteredIssues = [...issues];\r\n        updateIssueStats();\r\n        renderIssues();\r\n    } catch (error) {\r\n        console.error(\"Failed to load issues:\", error);\r\n        issueListEl.innerHTML = '<div class=\"empty\">Failed to load issue records.</div>';\r\n    }\r\n}\r\n\r\nfunction updateIssueStats() {\r\n    const issuedCount = issues.filter((item) => item.status === \"issued\").length;\r\n    const returnedCount = issues.filter((item) => item.status === \"returned\").length;\r\n    const dueTodayCount = issues.filter(isDueToday).length;\r\n    const overdueCount = issues.filter(isOverdue).length;\r\n    issuedBooksStatEl.textContent = issuedCount;\r\n    returnedBooksStatEl.textContent = returnedCount;\r\n    if (dueTodayStatEl) dueTodayStatEl.textContent = dueTodayCount;\r\n    if (overdueBooksStatEl) overdueBooksStatEl.textContent = overdueCount;\r\n}\r\n\r\nfunction renderIssues() {\r\n    issueListEl.innerHTML = \"\";\r\n    if (filteredIssues.length === 0) {\r\n        issueListEl.innerHTML = '<div class=\"empty\">No book records found.</div>';\r\n        return;\r\n    }\r\n\r\n    filteredIssues\r\n        .sort((a, b) => {\r\n            const aTime = getIssuedDate(a)?.getTime() || 0;\r\n            const bTime = getIssuedDate(b)?.getTime() || 0;\r\n            return bTime - aTime;\r\n        })\r\n        .forEach((entry) => {\r\n            const issuedDate = formatDateTime(entry.issuedAt || entry.issuedAtMs);\r\n            const returnedDate = entry.returnedAt || entry.returnedAtMs\r\n                ? formatDateTime(entry.returnedAt || entry.returnedAtMs)\r\n                : \"-\";\r\n            const dueDate = getDueDate(entry);\r\n            const ageDays = getIssueAgeDays(entry);\r\n            const overdue = isOverdue(entry);\r\n            const issuedBy = entry.issuedByName || entry.issuedByEmail || entry.issuedBy || \"Library staff\";\r\n            const statusPill = entry.status === \"returned\"\r\n                ? '<span class=\"pill pill-returned\">RETURNED</span>'\r\n                : overdue\r\n                    ? '<span class=\"pill pill-overdue\">OVERDUE</span>'\r\n                    : '<span class=\"pill pill-issued\">ISSUED</span>';\r\n\r\n            const row = document.createElement(\"div\");\r\n            row.className = \"row issue-row\";\r\n            row.innerHTML = `\r\n                <div class=\"row-main\">\r\n                    <span class=\"row-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15Z\"></path><path d=\"M8 7h8\"></path><path d=\"M8 11h6\"></path></svg></span>\r\n                    <div>\r\n                        <strong>${esc(entry.bookNumber || \"-\")}</strong> ${statusPill}<br>\r\n                        <small>Title: ${esc(entry.bookTitle || \"-\")}</small><br>\r\n                        <small>Student: ${esc(entry.studentName || \"-\")} (${esc(entry.studentId || \"-\")})</small><br>\r\n                        <small>Issued: ${esc(issuedDate)} | Return by: ${esc(formatDateOnly(dueDate))} | Returned: ${esc(returnedDate)}</small><br>\r\n                        <small>Issued by: ${esc(issuedBy)} | Age: ${ageDays === null ? \"N/A\" : `${ageDays} day(s)`}</small>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row-actions\">\r\n                ${entry.status === \"issued\"\r\n                    ? '<button class=\"btn btn-primary\" data-action=\"renew\">Renew</button><button class=\"btn btn-success\" data-action=\"return\">Mark Returned</button>'\r\n                    : '<span class=\"muted\">Completed</span>'}\r\n                </div>\r\n            `;\r\n\r\n            if (entry.status === \"issued\") {\r\n                row.querySelector('[data-action=\"return\"]').addEventListener(\"click\", async () => {\r\n                    await markReturned(entry.id);\r\n                });\r\n                row.querySelector('[data-action=\"renew\"]').addEventListener(\"click\", async () => {\r\n                    await renewIssue(entry.id);\r\n                });\r\n            }\r\n            issueListEl.appendChild(row);\r\n        });\r\n}\r\n\r\nwindow.issueBook = async () => {\r\n    if (issueSubmitButtonEl?.disabled) return;\r\n    const studentId = issueStudentIdEl.value.trim();\r\n    const bookNumber = issueBookNumberEl.value.trim();\r\n    const bookTitle = issueBookTitleEl.value.trim();\r\n\r\n    if (!studentId || !bookNumber) {\r\n        alert(\"Student ID and Book Number are required.\");\r\n        return;\r\n    }\r\n\r\n    const student = students.find((s) => (s.studentId || \"\").toLowerCase() === studentId.toLowerCase());\r\n    if (!student) {\r\n        alert(\"Student not found. Please enter valid Student ID.\");\r\n        return;\r\n    }\r\n    if (student.tcIssued) {\r\n        alert(\"Transfer Certificate issued for this student. Books cannot be issued.\");\r\n        return;\r\n    }\r\n\r\n    const alreadyIssued = issues.find((item) =>\r\n        (item.bookNumber || \"\").toLowerCase() === bookNumber.toLowerCase() && item.status === \"issued\"\r\n    );\r\n    if (alreadyIssued) {\r\n        alert(\"This book is already issued and not returned yet.\");\r\n        return;\r\n    }\r\n\r\n    try {\r\n        issueSubmitButtonEl?.classList.add(\"sx-action-loading\");\r\n        if (issueSubmitButtonEl) issueSubmitButtonEl.disabled = true;\r\n        const issuedOn = new Date();\r\n        const maxDaysAllowed = normalizeMaxDays(librarySettings.maxDays);\r\n        const dueDate = addDays(issuedOn, maxDaysAllowed);\r\n        await addDoc(collection(db, \"schools\", adminId, \"library_issues\"), {\r\n            studentRefId: student.id || null,\r\n            studentId: student.studentId || studentId,\r\n            studentName: student.name || \"\",\r\n            class: student.class || \"\",\r\n            section: student.section || \"\",\r\n            bookNumber,\r\n            bookTitle: bookTitle || \"\",\r\n            status: \"issued\",\r\n            issuedBy: auth.currentUser.uid,\r\n            issuedByName: currentLibrarian?.name || \"Librarian\",\r\n            issuedByEmail: currentLibrarian?.email || \"\",\r\n            issuedAt: serverTimestamp(),\r\n            issuedAtMs: issuedOn.getTime(),\r\n            maxDaysAllowed,\r\n            dueDate,\r\n            dueDateMs: dueDate.getTime(),\r\n            returnedAt: null,\r\n            returnedAtMs: null\r\n        });\r\n\r\n        issueBookNumberEl.value = \"\";\r\n        issueBookTitleEl.value = \"\";\r\n        await loadIssues();\r\n        alert(\"Book issued successfully.\");\r\n    } catch (error) {\r\n        console.error(\"Issue failed:\", error);\r\n        alert(\"Failed to issue book.\");\r\n    } finally {\r\n        issueSubmitButtonEl?.classList.remove(\"sx-action-loading\");\r\n        if (issueSubmitButtonEl) issueSubmitButtonEl.disabled = false;\r\n    }\r\n};\r\n\r\nasync function markReturned(issueId) {\r\n    if (!confirm(\"Mark this book as returned?\")) return;\r\n    try {\r\n        await updateDoc(doc(db, \"schools\", adminId, \"library_issues\", issueId), {\r\n            status: \"returned\",\r\n            returnedAt: serverTimestamp(),\r\n            returnedAtMs: Date.now()\r\n        });\r\n        await loadIssues();\r\n    } catch (error) {\r\n        console.error(\"Return update failed:\", error);\r\n        alert(\"Failed to update return status.\");\r\n    }\r\n}\r\n\r\nstudentSearchEl.addEventListener(\"input\", () => {\r\n    const q = studentSearchEl.value.trim().toLowerCase();\r\n    filteredStudents = students.filter((student) => {\r\n        const sid = (student.studentId || \"\").toLowerCase();\r\n        const name = (student.name || \"\").toLowerCase();\r\n        return sid.includes(q) || name.includes(q);\r\n    });\r\n    studentPage = 1;\r\n    renderStudents();\r\n});\r\n\r\nstudentPageSizeEl?.addEventListener(\"change\", () => {\r\n    studentPage = 1;\r\n    renderStudents();\r\n});\r\n\r\nfunction applyIssueFilters() {\r\n    const q = issueSearchEl.value.trim().toLowerCase();\r\n    const status = statusFilterEl.value;\r\n    const minAgeRaw = issueAgeFilterEl.value.trim();\r\n    const minAge = Number(minAgeRaw);\r\n    const hasMinAge = minAgeRaw !== \"\" && Number.isFinite(minAge) && minAge >= 0;\r\n    const dueFilter = dueFilterEl.value;\r\n    const endOfToday = new Date();\r\n    endOfToday.setHours(23, 59, 59, 999);\r\n\r\n    filteredIssues = issues.filter((entry) => {\r\n        const matchesSearch =\r\n            (entry.bookNumber || \"\").toLowerCase().includes(q) ||\r\n            (entry.bookTitle || \"\").toLowerCase().includes(q) ||\r\n            (entry.studentId || \"\").toLowerCase().includes(q) ||\r\n            (entry.studentName || \"\").toLowerCase().includes(q);\r\n        const matchesStatus = status === \"all\" ? true : entry.status === status;\r\n        const ageDays = getIssueAgeDays(entry);\r\n        const matchesAge = !hasMinAge || (ageDays !== null && ageDays >= minAge);\r\n        const dueDate = getDueDate(entry);\r\n        const matchesDue = dueFilter === \"all\"\r\n            ? true\r\n            : dueFilter === \"overdue\"\r\n                ? isOverdue(entry)\r\n                : entry.status !== \"returned\" && dueDate && dueDate.getTime() <= endOfToday.getTime();\r\n        return matchesSearch && matchesStatus && matchesAge && matchesDue;\r\n    });\r\n    renderIssues();\r\n}\r\n\r\nasync function renewIssue(issueId) {\r\n    const entry = issues.find((item) => item.id === issueId);\r\n    if (!entry) return;\r\n    const nextDue = addDays(new Date(), normalizeMaxDays(librarySettings.maxDays));\r\n    try {\r\n        await updateDoc(doc(db, \"schools\", adminId, \"library_issues\", issueId), {\r\n            dueDate: nextDue,\r\n            dueDateMs: nextDue.getTime(),\r\n            renewedAt: serverTimestamp(),\r\n            renewedAtMs: Date.now(),\r\n            renewedBy: auth.currentUser.uid\r\n        });\r\n        await loadIssues();\r\n    } catch (error) {\r\n        console.error(\"Renew failed:\", error);\r\n        alert(\"Failed to renew book.\");\r\n    }\r\n}\r\n\r\nfunction updateSelectedStudentCard(student) {\r\n    if (!selectedStudentCardEl) return;\r\n    const activeIssues = issues.filter((entry) => entry.status === \"issued\" && entry.studentId === student.studentId);\r\n    selectedStudentCardEl.innerHTML = `<strong>${esc(student.name || \"Student\")} (${esc(student.studentId || \"-\")})</strong>Class ${esc(student.class || \"-\")}-${esc(student.section || \"-\")} | Active books: ${activeIssues.length}`;\r\n}\r\n\r\nwindow.focusIssueForm = () => {\r\n    issueStudentIdEl.focus();\r\n};\r\n\r\nwindow.showDueToday = () => {\r\n    dueFilterEl.value = \"due-now\";\r\n    statusFilterEl.value = \"issued\";\r\n    applyIssueFilters();\r\n};\r\n\r\nwindow.showOverdue = () => {\r\n    dueFilterEl.value = \"overdue\";\r\n    statusFilterEl.value = \"issued\";\r\n    applyIssueFilters();\r\n};\r\n\r\nwindow.clearLibraryFilters = () => {\r\n    issueSearchEl.value = \"\";\r\n    statusFilterEl.value = \"all\";\r\n    issueAgeFilterEl.value = \"\";\r\n    dueFilterEl.value = \"all\";\r\n    filteredIssues = [...issues];\r\n    renderIssues();\r\n};\r\n\r\nissueSearchEl.addEventListener(\"input\", applyIssueFilters);\r\nstatusFilterEl.addEventListener(\"change\", applyIssueFilters);\r\nissueAgeFilterEl.addEventListener(\"input\", applyIssueFilters);\r\ndueFilterEl.addEventListener(\"change\", applyIssueFilters);\r\n</script>\r\n<script src=\"library-portal.js\"></script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"library-portal.css"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged, signOut } from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore,\r\n    doc,\r\n    getDoc,\r\n    collection,\r\n    getDocs,\r\n    addDoc,\r\n    updateDoc,\r\n    setDoc,\r\n    serverTimestamp\r\n} from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst welcomeText = document.getElementById(\"welcomeText\");\r\nconst studentListEl = document.getElementById(\"studentList\");\r\nconst issueListEl = document.getElementById(\"issueList\");\r\nconst totalStudentsStatEl = document.getElementById(\"totalStudentsStat\");\r\nconst issuedBooksStatEl = document.getElementById(\"issuedBooksStat\");\r\nconst returnedBooksStatEl = document.getElementById(\"returnedBooksStat\");\r\nconst maxDaysStatEl = document.getElementById(\"maxDaysStat\");\r\nconst dueTodayStatEl = document.getElementById(\"dueTodayStat\");\r\nconst overdueBooksStatEl = document.getElementById(\"overdueBooksStat\");\r\nconst studentSearchEl = document.getElementById(\"studentSearch\");\r\nconst studentPageSizeEl = document.getElementById(\"studentPageSize\");\r\nconst studentPagerEl = document.getElementById(\"studentPager\");\r\nconst issueSearchEl = document.getElementById(\"issueSearch\");\r\nconst statusFilterEl = document.getElementById(\"statusFilter\");\r\nconst issueAgeFilterEl = document.getElementById(\"issueAgeFilter\");\r\nconst dueFilterEl = document.getElementById(\"dueFilter\");\r\nconst issueStudentIdEl = document.getElementById(\"issueStudentId\");\r\nconst issueBookNumberEl = document.getElementById(\"issueBookNumber\");\r\nconst issueBookTitleEl = document.getElementById(\"issueBookTitle\");\r\nconst issueSubmitButtonEl = document.querySelector(\".issue-submit\");\r\nconst maxDaysInputEl = document.getElementById(\"maxDaysInput\");\r\nconst selectedStudentCardEl = document.getElementById(\"selectedStudentCard\");\r\nconst librarySidebarEl = document.getElementById(\"librarySidebar\");\r\nconst librarySidebarOverlayEl = document.getElementById(\"librarySidebarOverlay\");\r\nconst libraryMenuButtonEl = document.getElementById(\"libraryMenuButton\");\r\n\r\nlet adminId = null;\r\nlet currentLibrarian = null;\r\nlet librarySettings = { maxDays: 14 };\r\nlet students = [];\r\nlet issues = [];\r\nlet filteredStudents = [];\r\nlet filteredIssues = [];\r\nlet studentPage = 1;\r\n\r\nfunction closeLibrarySidebar() {\r\n    librarySidebarEl?.classList.remove(\"open\");\r\n    librarySidebarOverlayEl?.classList.remove(\"open\");\r\n    librarySidebarOverlayEl?.setAttribute(\"aria-hidden\", \"true\");\r\n    libraryMenuButtonEl?.setAttribute(\"aria-expanded\", \"false\");\r\n}\r\n\r\nfunction openLibrarySidebar() {\r\n    librarySidebarEl?.classList.add(\"open\");\r\n    librarySidebarOverlayEl?.classList.add(\"open\");\r\n    librarySidebarOverlayEl?.setAttribute(\"aria-hidden\", \"false\");\r\n    libraryMenuButtonEl?.setAttribute(\"aria-expanded\", \"true\");\r\n}\r\n\r\nlibraryMenuButtonEl?.addEventListener(\"click\", () => {\r\n    librarySidebarEl?.classList.contains(\"open\") ? closeLibrarySidebar() : openLibrarySidebar();\r\n});\r\nlibrarySidebarOverlayEl?.addEventListener(\"click\", closeLibrarySidebar);\r\nlibrarySidebarEl?.querySelectorAll(\"a\").forEach((link) => link.addEventListener(\"click\", closeLibrarySidebar));\r\ndocument.addEventListener(\"keydown\", (event) => {\r\n    if (event.key === \"Escape\") closeLibrarySidebar();\r\n});\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    if (!user) {\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n    if (!userDoc.exists() || userDoc.data().role !== \"librarian\") {\r\n        alert(\"Access denied. Librarian account required.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n\r\n    const data = userDoc.data();\r\n    adminId = data.adminId || data.schoolId || \"\";\r\n    currentLibrarian = {\r\n        uid: user.uid,\r\n        name: data.name || \"Librarian\",\r\n        email: data.email || user.email || \"\"\r\n    };\r\n    if (!adminId) {\r\n        alert(\"Admin mapping missing for librarian account.\");\r\n        window.location.href = \"#/index.html\";\r\n        return;\r\n    }\r\n    welcomeText.textContent = `Welcome ${data.name || \"Librarian\"} (${data.email || user.email})`;\r\n    await loadLibrarySettings();\r\n    await loadStudents();\r\n    await loadIssues();\r\n});\r\n\r\nwindow.logout = async () => {\r\n    try {\r\n        await signOut(auth);\r\n        window.location.href = \"#/index.html\";\r\n    } catch (error) {\r\n        alert(\"Logout failed.\");\r\n    }\r\n};\r\n\r\nfunction esc(value) {\r\n    return String(value ?? \"\")\r\n        .replace(/&/g, \"&amp;\")\r\n        .replace(/</g, \"&lt;\")\r\n        .replace(/>/g, \"&gt;\")\r\n        .replace(/\"/g, \"&quot;\")\r\n        .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction normalizeMaxDays(value) {\r\n    const days = Number(value);\r\n    if (!Number.isFinite(days) || days < 1) return 14;\r\n    return Math.min(365, Math.floor(days));\r\n}\r\n\r\nfunction toDate(value) {\r\n    if (!value) return null;\r\n    if (value.toDate) return value.toDate();\r\n    if (typeof value.seconds === \"number\") return new Date(value.seconds * 1000);\r\n    const parsed = new Date(value);\r\n    return Number.isNaN(parsed.getTime()) ? null : parsed;\r\n}\r\n\r\nfunction addDays(date, days) {\r\n    const result = new Date(date);\r\n    result.setDate(result.getDate() + days);\r\n    return result;\r\n}\r\n\r\nfunction getIssuedDate(entry) {\r\n    return toDate(entry.issuedAt) || toDate(entry.issuedAtMs);\r\n}\r\n\r\nfunction getMaxDaysForEntry(entry) {\r\n    return normalizeMaxDays(entry.maxDaysAllowed || librarySettings.maxDays);\r\n}\r\n\r\nfunction getDueDate(entry) {\r\n    const storedDueDate = toDate(entry.dueDate) || toDate(entry.dueDateMs);\r\n    if (storedDueDate) return storedDueDate;\r\n    const issued = getIssuedDate(entry);\r\n    return issued ? addDays(issued, getMaxDaysForEntry(entry)) : null;\r\n}\r\n\r\nfunction getIssueAgeDays(entry) {\r\n    const issued = getIssuedDate(entry);\r\n    if (!issued) return null;\r\n    return Math.max(0, Math.floor((Date.now() - issued.getTime()) / 86400000));\r\n}\r\n\r\nfunction isOverdue(entry) {\r\n    if (entry.status === \"returned\") return false;\r\n    const dueDate = getDueDate(entry);\r\n    if (!dueDate) return false;\r\n    const startOfToday = new Date();\r\n    startOfToday.setHours(0, 0, 0, 0);\r\n    return dueDate.getTime() < startOfToday.getTime();\r\n}\r\n\r\nfunction isDueToday(entry) {\r\n    if (entry.status === \"returned\") return false;\r\n    const dueDate = getDueDate(entry);\r\n    if (!dueDate) return false;\r\n    const endOfToday = new Date();\r\n    endOfToday.setHours(23, 59, 59, 999);\r\n    return dueDate.getTime() <= endOfToday.getTime();\r\n}\r\n\r\nfunction formatDateTime(value) {\r\n    const date = toDate(value);\r\n    return date ? date.toLocaleString() : \"N/A\";\r\n}\r\n\r\nfunction formatDateOnly(value) {\r\n    const date = toDate(value);\r\n    return date ? date.toLocaleDateString() : \"N/A\";\r\n}\r\n\r\nasync function loadLibrarySettings() {\r\n    try {\r\n        const settingsSnap = await getDoc(doc(db, \"schools\", adminId, \"settings\", \"library\"));\r\n        librarySettings = {\r\n            maxDays: normalizeMaxDays(settingsSnap.exists() ? settingsSnap.data().maxDays : 14)\r\n        };\r\n    } catch (error) {\r\n        console.warn(\"Library settings load failed:\", error);\r\n        librarySettings = { maxDays: 14 };\r\n    }\r\n    maxDaysInputEl.value = String(librarySettings.maxDays);\r\n    maxDaysStatEl.textContent = librarySettings.maxDays;\r\n}\r\n\r\nwindow.saveLibrarySettings = async () => {\r\n    const maxDays = normalizeMaxDays(maxDaysInputEl.value);\r\n    try {\r\n        await setDoc(doc(db, \"schools\", adminId, \"settings\", \"library\"), {\r\n            maxDays,\r\n            updatedAt: serverTimestamp(),\r\n            updatedBy: auth.currentUser.uid\r\n        }, { merge: true });\r\n        librarySettings.maxDays = maxDays;\r\n        maxDaysInputEl.value = String(maxDays);\r\n        maxDaysStatEl.textContent = maxDays;\r\n        renderIssues();\r\n        alert(\"Library rules saved.\");\r\n    } catch (error) {\r\n        console.error(\"Library settings save failed:\", error);\r\n        alert(\"Failed to save library rules.\");\r\n    }\r\n};\r\n\r\nasync function loadStudents() {\r\n    studentListEl.innerHTML = '<div class=\"empty sx-inline-loading\">Loading students...</div>';\r\n    try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", adminId, \"students\"));\r\n        students = snapshot.docs.map((docSnap) => ({\r\n            id: docSnap.id,\r\n            ...docSnap.data()\r\n        }));\r\n        filteredStudents = [...students];\r\n        totalStudentsStatEl.textContent = students.length;\r\n        renderStudents();\r\n    } catch (error) {\r\n        console.error(\"Failed to load students:\", error);\r\n        studentListEl.innerHTML = '<div class=\"empty\">Failed to load students.</div>';\r\n    }\r\n}\r\n\r\nfunction renderStudents() {\r\n    studentListEl.innerHTML = \"\";\r\n    if (filteredStudents.length === 0) {\r\n        studentListEl.innerHTML = '<div class=\"empty\">No students found.</div>';\r\n        renderStudentPager(0, 0, 1);\r\n        return;\r\n    }\r\n\r\n    const pageSizeValue = studentPageSizeEl?.value || \"25\";\r\n    const pageSize = pageSizeValue === \"all\" ? filteredStudents.length : Number(pageSizeValue || 25);\r\n    const totalPages = Math.max(1, Math.ceil(filteredStudents.length / Math.max(1, pageSize)));\r\n    studentPage = Math.min(Math.max(1, studentPage), totalPages);\r\n    const start = pageSizeValue === \"all\" ? 0 : (studentPage - 1) * pageSize;\r\n    const visibleStudents = pageSizeValue === \"all\" ? filteredStudents : filteredStudents.slice(start, start + pageSize);\r\n\r\n    visibleStudents.forEach((student) => {\r\n        const tc = !!student.tcIssued;\r\n        const row = document.createElement(\"div\");\r\n        row.className = \"row\" + (tc ? \" row-tc\" : \"\");\r\n        row.innerHTML = `\r\n            <div class=\"row-main\">\r\n                <span class=\"row-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"></circle><path d=\"M4 21a8 8 0 0 1 16 0\"></path></svg></span>\r\n                <div>\r\n                    <strong>${student.name || \"N/A\"}</strong>\r\n                    ${tc ? ' <span class=\"pill pill-tc\">TC Issued</span>' : \"\"}<br>\r\n                    <small>ID: ${student.studentId || \"N/A\"} | Class: ${student.class || \"-\"}-${student.section || \"-\"}</small>\r\n                    ${tc ? \"<br><small style=\\\"color:#b91c1c;\\\">Books cannot be issued - student has left (TC).</small>\" : \"\"}\r\n                </div>\r\n            </div>\r\n            <button class=\"btn btn-success\" ${tc ? \"disabled\" : \"\"}>${tc ? \"Blocked\" : \"Select\"}</button>\r\n        `;\r\n        const btn = row.querySelector(\"button\");\r\n        btn.addEventListener(\"click\", () => {\r\n            if (tc) {\r\n                alert(\"This student has a Transfer Certificate issued. Library issue is not allowed.\");\r\n                return;\r\n            }\r\n            issueStudentIdEl.value = student.studentId || \"\";\r\n            updateSelectedStudentCard(student);\r\n            issueStudentIdEl.focus();\r\n        });\r\n        studentListEl.appendChild(row);\r\n    });\r\n    renderStudentPager(filteredStudents.length, visibleStudents.length, totalPages);\r\n}\r\n\r\nfunction renderStudentPager(total, visible, totalPages) {\r\n    if (!studentPagerEl) return;\r\n    if (!total) {\r\n        studentPagerEl.innerHTML = \"\";\r\n        return;\r\n    }\r\n    const pageSizeValue = studentPageSizeEl?.value || \"25\";\r\n    const start = pageSizeValue === \"all\" ? 1 : ((studentPage - 1) * Number(pageSizeValue) + 1);\r\n    const end = pageSizeValue === \"all\" ? total : Math.min(total, start + visible - 1);\r\n    studentPagerEl.innerHTML = `\r\n        <span>${start}-${end} of ${total}</span>\r\n        <button type=\"button\" id=\"studentPrevPage\" ${studentPage <= 1 || pageSizeValue === \"all\" ? \"disabled\" : \"\"}>Prev</button>\r\n        <span>Page ${pageSizeValue === \"all\" ? 1 : studentPage}/${pageSizeValue === \"all\" ? 1 : totalPages}</span>\r\n        <button type=\"button\" id=\"studentNextPage\" ${studentPage >= totalPages || pageSizeValue === \"all\" ? \"disabled\" : \"\"}>Next</button>\r\n    `;\r\n    document.getElementById(\"studentPrevPage\")?.addEventListener(\"click\", () => {\r\n        studentPage = Math.max(1, studentPage - 1);\r\n        renderStudents();\r\n    });\r\n    document.getElementById(\"studentNextPage\")?.addEventListener(\"click\", () => {\r\n        studentPage = Math.min(totalPages, studentPage + 1);\r\n        renderStudents();\r\n    });\r\n}\r\n\r\nasync function loadIssues() {\r\n    issueListEl.innerHTML = '<div class=\"empty sx-inline-loading\">Loading issue records...</div>';\r\n    try {\r\n        const snapshot = await getDocs(collection(db, \"schools\", adminId, \"library_issues\"));\r\n        issues = snapshot.docs.map((docSnap) => ({\r\n            id: docSnap.id,\r\n            ...docSnap.data()\r\n        }));\r\n        filteredIssues = [...issues];\r\n        updateIssueStats();\r\n        renderIssues();\r\n    } catch (error) {\r\n        console.error(\"Failed to load issues:\", error);\r\n        issueListEl.innerHTML = '<div class=\"empty\">Failed to load issue records.</div>';\r\n    }\r\n}\r\n\r\nfunction updateIssueStats() {\r\n    const issuedCount = issues.filter((item) => item.status === \"issued\").length;\r\n    const returnedCount = issues.filter((item) => item.status === \"returned\").length;\r\n    const dueTodayCount = issues.filter(isDueToday).length;\r\n    const overdueCount = issues.filter(isOverdue).length;\r\n    issuedBooksStatEl.textContent = issuedCount;\r\n    returnedBooksStatEl.textContent = returnedCount;\r\n    if (dueTodayStatEl) dueTodayStatEl.textContent = dueTodayCount;\r\n    if (overdueBooksStatEl) overdueBooksStatEl.textContent = overdueCount;\r\n}\r\n\r\nfunction renderIssues() {\r\n    issueListEl.innerHTML = \"\";\r\n    if (filteredIssues.length === 0) {\r\n        issueListEl.innerHTML = '<div class=\"empty\">No book records found.</div>';\r\n        return;\r\n    }\r\n\r\n    filteredIssues\r\n        .sort((a, b) => {\r\n            const aTime = getIssuedDate(a)?.getTime() || 0;\r\n            const bTime = getIssuedDate(b)?.getTime() || 0;\r\n            return bTime - aTime;\r\n        })\r\n        .forEach((entry) => {\r\n            const issuedDate = formatDateTime(entry.issuedAt || entry.issuedAtMs);\r\n            const returnedDate = entry.returnedAt || entry.returnedAtMs\r\n                ? formatDateTime(entry.returnedAt || entry.returnedAtMs)\r\n                : \"-\";\r\n            const dueDate = getDueDate(entry);\r\n            const ageDays = getIssueAgeDays(entry);\r\n            const overdue = isOverdue(entry);\r\n            const issuedBy = entry.issuedByName || entry.issuedByEmail || entry.issuedBy || \"Library staff\";\r\n            const statusPill = entry.status === \"returned\"\r\n                ? '<span class=\"pill pill-returned\">RETURNED</span>'\r\n                : overdue\r\n                    ? '<span class=\"pill pill-overdue\">OVERDUE</span>'\r\n                    : '<span class=\"pill pill-issued\">ISSUED</span>';\r\n\r\n            const row = document.createElement(\"div\");\r\n            row.className = \"row issue-row\";\r\n            row.innerHTML = `\r\n                <div class=\"row-main\">\r\n                    <span class=\"row-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M4 4.5A2.5 2.5 0 0 1 6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15Z\"></path><path d=\"M8 7h8\"></path><path d=\"M8 11h6\"></path></svg></span>\r\n                    <div>\r\n                        <strong>${esc(entry.bookNumber || \"-\")}</strong> ${statusPill}<br>\r\n                        <small>Title: ${esc(entry.bookTitle || \"-\")}</small><br>\r\n                        <small>Student: ${esc(entry.studentName || \"-\")} (${esc(entry.studentId || \"-\")})</small><br>\r\n                        <small>Issued: ${esc(issuedDate)} | Return by: ${esc(formatDateOnly(dueDate))} | Returned: ${esc(returnedDate)}</small><br>\r\n                        <small>Issued by: ${esc(issuedBy)} | Age: ${ageDays === null ? \"N/A\" : `${ageDays} day(s)`}</small>\r\n                    </div>\r\n                </div>\r\n                <div class=\"row-actions\">\r\n                ${entry.status === \"issued\"\r\n                    ? '<button class=\"btn btn-primary\" data-action=\"renew\">Renew</button><button class=\"btn btn-success\" data-action=\"return\">Mark Returned</button>'\r\n                    : '<span class=\"muted\">Completed</span>'}\r\n                </div>\r\n            `;\r\n\r\n            if (entry.status === \"issued\") {\r\n                row.querySelector('[data-action=\"return\"]').addEventListener(\"click\", async () => {\r\n                    await markReturned(entry.id);\r\n                });\r\n                row.querySelector('[data-action=\"renew\"]').addEventListener(\"click\", async () => {\r\n                    await renewIssue(entry.id);\r\n                });\r\n            }\r\n            issueListEl.appendChild(row);\r\n        });\r\n}\r\n\r\nwindow.issueBook = async () => {\r\n    if (issueSubmitButtonEl?.disabled) return;\r\n    const studentId = issueStudentIdEl.value.trim();\r\n    const bookNumber = issueBookNumberEl.value.trim();\r\n    const bookTitle = issueBookTitleEl.value.trim();\r\n\r\n    if (!studentId || !bookNumber) {\r\n        alert(\"Student ID and Book Number are required.\");\r\n        return;\r\n    }\r\n\r\n    const student = students.find((s) => (s.studentId || \"\").toLowerCase() === studentId.toLowerCase());\r\n    if (!student) {\r\n        alert(\"Student not found. Please enter valid Student ID.\");\r\n        return;\r\n    }\r\n    if (student.tcIssued) {\r\n        alert(\"Transfer Certificate issued for this student. Books cannot be issued.\");\r\n        return;\r\n    }\r\n\r\n    const alreadyIssued = issues.find((item) =>\r\n        (item.bookNumber || \"\").toLowerCase() === bookNumber.toLowerCase() && item.status === \"issued\"\r\n    );\r\n    if (alreadyIssued) {\r\n        alert(\"This book is already issued and not returned yet.\");\r\n        return;\r\n    }\r\n\r\n    try {\r\n        issueSubmitButtonEl?.classList.add(\"sx-action-loading\");\r\n        if (issueSubmitButtonEl) issueSubmitButtonEl.disabled = true;\r\n        const issuedOn = new Date();\r\n        const maxDaysAllowed = normalizeMaxDays(librarySettings.maxDays);\r\n        const dueDate = addDays(issuedOn, maxDaysAllowed);\r\n        await addDoc(collection(db, \"schools\", adminId, \"library_issues\"), {\r\n            studentRefId: student.id || null,\r\n            studentId: student.studentId || studentId,\r\n            studentName: student.name || \"\",\r\n            class: student.class || \"\",\r\n            section: student.section || \"\",\r\n            bookNumber,\r\n            bookTitle: bookTitle || \"\",\r\n            status: \"issued\",\r\n            issuedBy: auth.currentUser.uid,\r\n            issuedByName: currentLibrarian?.name || \"Librarian\",\r\n            issuedByEmail: currentLibrarian?.email || \"\",\r\n            issuedAt: serverTimestamp(),\r\n            issuedAtMs: issuedOn.getTime(),\r\n            maxDaysAllowed,\r\n            dueDate,\r\n            dueDateMs: dueDate.getTime(),\r\n            returnedAt: null,\r\n            returnedAtMs: null\r\n        });\r\n\r\n        issueBookNumberEl.value = \"\";\r\n        issueBookTitleEl.value = \"\";\r\n        await loadIssues();\r\n        alert(\"Book issued successfully.\");\r\n    } catch (error) {\r\n        console.error(\"Issue failed:\", error);\r\n        alert(\"Failed to issue book.\");\r\n    } finally {\r\n        issueSubmitButtonEl?.classList.remove(\"sx-action-loading\");\r\n        if (issueSubmitButtonEl) issueSubmitButtonEl.disabled = false;\r\n    }\r\n};\r\n\r\nasync function markReturned(issueId) {\r\n    if (!confirm(\"Mark this book as returned?\")) return;\r\n    try {\r\n        await updateDoc(doc(db, \"schools\", adminId, \"library_issues\", issueId), {\r\n            status: \"returned\",\r\n            returnedAt: serverTimestamp(),\r\n            returnedAtMs: Date.now()\r\n        });\r\n        await loadIssues();\r\n    } catch (error) {\r\n        console.error(\"Return update failed:\", error);\r\n        alert(\"Failed to update return status.\");\r\n    }\r\n}\r\n\r\nstudentSearchEl.addEventListener(\"input\", () => {\r\n    const q = studentSearchEl.value.trim().toLowerCase();\r\n    filteredStudents = students.filter((student) => {\r\n        const sid = (student.studentId || \"\").toLowerCase();\r\n        const name = (student.name || \"\").toLowerCase();\r\n        return sid.includes(q) || name.includes(q);\r\n    });\r\n    studentPage = 1;\r\n    renderStudents();\r\n});\r\n\r\nstudentPageSizeEl?.addEventListener(\"change\", () => {\r\n    studentPage = 1;\r\n    renderStudents();\r\n});\r\n\r\nfunction applyIssueFilters() {\r\n    const q = issueSearchEl.value.trim().toLowerCase();\r\n    const status = statusFilterEl.value;\r\n    const minAgeRaw = issueAgeFilterEl.value.trim();\r\n    const minAge = Number(minAgeRaw);\r\n    const hasMinAge = minAgeRaw !== \"\" && Number.isFinite(minAge) && minAge >= 0;\r\n    const dueFilter = dueFilterEl.value;\r\n    const endOfToday = new Date();\r\n    endOfToday.setHours(23, 59, 59, 999);\r\n\r\n    filteredIssues = issues.filter((entry) => {\r\n        const matchesSearch =\r\n            (entry.bookNumber || \"\").toLowerCase().includes(q) ||\r\n            (entry.bookTitle || \"\").toLowerCase().includes(q) ||\r\n            (entry.studentId || \"\").toLowerCase().includes(q) ||\r\n            (entry.studentName || \"\").toLowerCase().includes(q);\r\n        const matchesStatus = status === \"all\" ? true : entry.status === status;\r\n        const ageDays = getIssueAgeDays(entry);\r\n        const matchesAge = !hasMinAge || (ageDays !== null && ageDays >= minAge);\r\n        const dueDate = getDueDate(entry);\r\n        const matchesDue = dueFilter === \"all\"\r\n            ? true\r\n            : dueFilter === \"overdue\"\r\n                ? isOverdue(entry)\r\n                : entry.status !== \"returned\" && dueDate && dueDate.getTime() <= endOfToday.getTime();\r\n        return matchesSearch && matchesStatus && matchesAge && matchesDue;\r\n    });\r\n    renderIssues();\r\n}\r\n\r\nasync function renewIssue(issueId) {\r\n    const entry = issues.find((item) => item.id === issueId);\r\n    if (!entry) return;\r\n    const nextDue = addDays(new Date(), normalizeMaxDays(librarySettings.maxDays));\r\n    try {\r\n        await updateDoc(doc(db, \"schools\", adminId, \"library_issues\", issueId), {\r\n            dueDate: nextDue,\r\n            dueDateMs: nextDue.getTime(),\r\n            renewedAt: serverTimestamp(),\r\n            renewedAtMs: Date.now(),\r\n            renewedBy: auth.currentUser.uid\r\n        });\r\n        await loadIssues();\r\n    } catch (error) {\r\n        console.error(\"Renew failed:\", error);\r\n        alert(\"Failed to renew book.\");\r\n    }\r\n}\r\n\r\nfunction updateSelectedStudentCard(student) {\r\n    if (!selectedStudentCardEl) return;\r\n    const activeIssues = issues.filter((entry) => entry.status === \"issued\" && entry.studentId === student.studentId);\r\n    selectedStudentCardEl.innerHTML = `<strong>${esc(student.name || \"Student\")} (${esc(student.studentId || \"-\")})</strong>Class ${esc(student.class || \"-\")}-${esc(student.section || \"-\")} | Active books: ${activeIssues.length}`;\r\n}\r\n\r\nwindow.focusIssueForm = () => {\r\n    issueStudentIdEl.focus();\r\n};\r\n\r\nwindow.showDueToday = () => {\r\n    dueFilterEl.value = \"due-now\";\r\n    statusFilterEl.value = \"issued\";\r\n    applyIssueFilters();\r\n};\r\n\r\nwindow.showOverdue = () => {\r\n    dueFilterEl.value = \"overdue\";\r\n    statusFilterEl.value = \"issued\";\r\n    applyIssueFilters();\r\n};\r\n\r\nwindow.clearLibraryFilters = () => {\r\n    issueSearchEl.value = \"\";\r\n    statusFilterEl.value = \"all\";\r\n    issueAgeFilterEl.value = \"\";\r\n    dueFilterEl.value = \"all\";\r\n    filteredIssues = [...issues];\r\n    renderIssues();\r\n};\r\n\r\nissueSearchEl.addEventListener(\"input\", applyIssueFilters);\r\nstatusFilterEl.addEventListener(\"change\", applyIssueFilters);\r\nissueAgeFilterEl.addEventListener(\"input\", applyIssueFilters);\r\ndueFilterEl.addEventListener(\"change\", applyIssueFilters);\r\n"},{"attributes":{"src":"library-portal.js"},"text":""},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""}]};
